let squadTab='health',recordFilter='all',recordSort='goals',recordYear=null;
const recordCompetitionNames={all:'전체 대회',league:'리그',cup:'컵',europe:'챔피언스리그'};
function recordYears(){return [season.year,...(season.statistics?.archive||[]).map(h=>h.year)].sort((a,b)=>b-a);}
function recordLeader(players,key){return [...players].filter(p=>p[key]>0).sort((a,b)=>b[key]-a[key]||b.minutes-a.minutes||a.name.localeCompare(b.name,'ko'))[0]||null;}
function selectSquadTab(tab){
 if(!['health','training','records'].includes(tab))return;
 if(squadTab!==tab){squadTab=tab;save();render();}
 $('squad-tab-'+tab)?.focus?.({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});
}
function renderRecords(){
 if(typeof view!=='undefined'&&view!=='squad')return;
 $('squad-tabs').innerHTML='<div class="squad-tabs" role="tablist" aria-label="선수단 보기"><button id="squad-tab-health" role="tab" aria-controls="squad-management" aria-selected="'+(squadTab==='health')+'" data-squad-tab="health">선수 관리</button><button id="squad-tab-training" role="tab" aria-controls="individual-training" aria-selected="'+(squadTab==='training')+'" data-squad-tab="training">훈련 센터</button><button id="squad-tab-records" role="tab" aria-controls="player-records" aria-selected="'+(squadTab==='records')+'" data-squad-tab="records">시즌 기록</button></div>';
 $('squad-management').hidden=squadTab!=='health';$('individual-training').hidden=squadTab!=='training';$('player-records').hidden=squadTab!=='records';
 document.querySelectorAll('[data-squad-tab]').forEach(b=>{b.tabIndex=b.dataset.squadTab===squadTab?0:-1;b.onclick=()=>selectSquadTab(b.dataset.squadTab);b.onkeydown=event=>{if(event.altKey||event.ctrlKey||event.metaKey)return;const tabs=['health','training','records'],index=tabs.indexOf(b.dataset.squadTab),next=event.key==='ArrowRight'?tabs[(index+1)%tabs.length]:event.key==='ArrowLeft'?tabs[(index+tabs.length-1)%tabs.length]:event.key==='Home'?tabs[0]:event.key==='End'?tabs.at(-1):null;if(next){event.preventDefault();selectSquadTab(next);}};});
 if(squadTab!=='records')return;
 const years=recordYears();if(!years.includes(recordYear))recordYear=season.year;
 const summary=ST.summary(season,recordFilter,recordYear),tier=S.divisionInfo(S.leagueForYear(season,recordYear)),current=recordYear===season.year,currentIds=new Set(Object.values(season.squad).map(p=>p.identity));
 const goalLeader=recordLeader(summary.players,'goals'),assistLeader=recordLeader(summary.players,'assists'),minuteLeader=recordLeader(summary.players,'minutes'),keeperLeader=recordLeader(summary.players.filter(p=>p.pos==='GK'),'cleanSheets');
 const sorted=[...summary.players].sort((a,b)=>b[recordSort]-a[recordSort]||b.goals-a.goals||b.assists-a.assists||b.minutes-a.minutes||a.name.localeCompare(b.name,'ko'));
 const leaderCard=(label,p,key,unit,empty)=>'<article class="record-leader"><span>'+label+'</span><strong>'+(p?playerUiText(p.name):empty)+'</strong><div><b>'+(p?p[key]:0)+'</b><small>'+unit+'</small></div></article>';
 const note=summary.partial?'업데이트 이후 확정한 경기부터 집계합니다. 이전에 진행한 경기의 득점은 선수 미지정으로 남을 수 있습니다.':'경기 결과를 확정하면 기록합니다. 승부차기 득점은 시즌 득점·도움에 포함하지 않습니다.';
 $('player-records').innerHTML=`<button type="button" id="open-career-records" class="secondary">모든 시즌 통산 기록 보기</button><div class="records-hero"><div><div class="eyebrow">선수 기록 / ${recordYear} 시즌 / 리그 ${tier.division}</div><h1>선수의 이름으로 남는 시즌.</h1><p>${tier.name} · ${recordCompetitionNames[recordFilter]} ${summary.matches}경기 집계<br>누가 골을 만들고, 누가 긴 시즌을 지탱했는지 살펴보세요.</p></div><div class="records-total"><span>우리 구단 득점</span><strong>${summary.goals}<small>골</small></strong><span>${summary.unassignedGoals?'선수 미지정 '+summary.unassignedGoals+'골':'출전 기록 '+summary.minutes.toLocaleString('ko-KR')+'분'}</span></div></div><div class="record-controls"><div class="record-filters" role="group" aria-label="기록 대회 선택">${Object.entries(recordCompetitionNames).map(([key,name])=>'<button data-record-filter="'+key+'" aria-pressed="'+(recordFilter===key)+'">'+name+'</button>').join('')}</div><label>시즌 <select id="record-year">${years.map(year=>'<option value="'+year+'" '+(year===recordYear?'selected':'')+'>'+year+'시즌'+(year===season.year?' · 현재 시즌':'')+'</option>').join('')}</select></label><label>정렬 <select id="record-sort">${[['goals','득점순'],['assists','도움순'],['minutes','출전 시간순'],['cleanSheets','무실점순']].map(([key,name])=>'<option value="'+key+'" '+(recordSort===key?'selected':'')+'>'+name+'</option>').join('')}</select></label></div><div class="record-leaders">${leaderCard('득점 선두',goalLeader,'goals','골','첫 골을 기다립니다.')}${leaderCard('도움 선두',assistLeader,'assists','도움','첫 도움을 기다립니다.')}${leaderCard('가장 오래 뛴 선수',minuteLeader,'minutes','분','첫 출전을 기다립니다.')}${leaderCard('골키퍼 무실점',keeperLeader,'cleanSheets','경기','첫 무실점을 기다립니다.')}</div><div class="panel-heading record-table-heading"><h2>${recordYear}시즌 선수 기록</h2><span>${summary.matches}경기 · ${current?'현재 선수와 이적 선수':'시즌 당시 출전 선수'}</span></div><div class="table-wrap"><table class="records-table"><thead><tr><th>선수</th><th>역할</th><th>출전</th><th>선발</th><th>득점</th><th>도움</th><th>출전 시간</th><th>무실점</th></tr></thead><tbody>${sorted.map(p=>`<tr class="${current&&!currentIds.has(p.identity)?'record-departed':''}"><th scope="row">${playerUiText(p.name)}${current&&!currentIds.has(p.identity)?'<small>이적한 선수 · 기록 보존</small>':F.identityProfile(p.identity)?.academy?'<small>유소년 센터 출신</small>':''}</th><td>${p.pos}</td><td>${p.apps}</td><td>${p.starts}</td><td class="${recordSort==='goals'?'record-focus':''}">${p.goals}</td><td class="${recordSort==='assists'?'record-focus':''}">${p.assists}</td><td class="${recordSort==='minutes'?'record-focus':''}">${p.minutes.toLocaleString('ko-KR')}<small>분</small></td><td class="${recordSort==='cleanSheets'?'record-focus':''}">${p.pos==='GK'?p.cleanSheets:'—'}</td></tr>`).join('')}</tbody></table></div>${!summary.matches?'<p class="records-empty">'+(current&&season.match?'선택한 대회의 경기 결과를 확정하면 첫 기록이 쌓입니다.':'이 시즌에는 선택한 대회의 집계 기록이 없습니다.')+'</p>':''}<p class="records-note">${note}<br>선발은 킥오프 때의 명단, 출전 시간은 실제 뛴 분을 셉니다. 무실점은 골키퍼가 90분을 뛰고 실점하지 않은 경기입니다.</p><div id="record-last-match"></div>`;
 $('open-career-records').onclick=()=>openCareerRecords();
 document.querySelectorAll('[data-record-filter]').forEach(b=>b.onclick=()=>{recordFilter=b.dataset.recordFilter;save();render();document.querySelector('[data-record-filter="'+recordFilter+'"]')?.focus?.({preventScroll:true});});
 $('record-year').onchange=e=>{recordYear=Number(e.target.value);save();render();$('record-year')?.focus?.({preventScroll:true});};$('record-sort').onchange=e=>{recordSort=e.target.value;save();render();$('record-sort')?.focus?.({preventScroll:true});};
 if(current)$('record-last-match').innerHTML=matchReviewMarkup(MatchReview.read(season),{compact:true});
}
function matchContributionsMarkup(){
 if(!state||state.phase!=='full')return '';const events=F.goalAttributions(state),people=new Map();
 for(const e of events){for(const [identity,key] of [[e.scorerIdentity,'goals'],[e.assistIdentity,'assists']]){if(!identity)continue;if(!people.has(identity))people.set(identity,{name:F.identityProfile(identity).name,goals:0,assists:0});people.get(identity)[key]++;}}
 const unknown=state.score[0]-events.length;return '<section class="match-contributions"><div class="eyebrow">득점 & 도움</div><h3>골을 만든 선수들</h3>'+(people.size?[...people.values()].map(p=>'<p><b>'+playerUiText(p.name)+'</b><span>'+[p.goals?p.goals+'골':'',p.assists?p.assists+'도움':''].filter(Boolean).join(' · ')+'</span></p>').join(''):'<p>선수에게 기록된 득점·도움이 없습니다.</p>')+(unknown?'<small>선수 미지정 '+unknown+'골 · 업데이트 전에 기록된 득점입니다.</small>':'')+'<small>결과 확정 후 시즌 기록에 반영합니다. 승부차기는 별도로 표시합니다.</small></section>';
}
